    sat: "ᱯᱨᱚᱫᱷᱟᱱ ᱢᱚᱱᱛᱨᱤ ᱚᱲᱟᱜ ᱡᱚᱡᱚᱱᱟ - ᱟᱹᱛᱩ", ks: "پردھان مَنتری آواس یوجَنا - دیہی"
