  "Direct conditional cash benefit of ₹5,000 for pregnant women and lactating mothers for healthcare and nutrition.": {
    hi: "गर्भवती महिलाओं और स्तनपान कराने वाली माताओं के स्वास्थ्य और पोषण के लिए ₹5,000 का सीधा सशर्त नकद लाभ।",
    bn: "গর্ভবতী মহিলা এবং স্তন্যদানকারী মায়েদের স্বাস্থ্য ও পুষ্টির জন্য ₹৫,০০০ এর প্রত্যক্ষ শর্তাধীন নগদ সুবিধা।",
    te: "గర్భిణీ స్త్రీలు మరియు పాలిచ్చే తల్లుల ఆరోగ్యం మరియు పోషణ కోసం ₹5,000 ప్రత్యక్ష షరతులతో కూడిన నగదు ప్రయోజనం.",
    mr: "गर्भवती महिला आणि स्तनदा मातांच्या आरोग्य आणि पोषणासाठी ₹५,००० चा थेट सशर्त रोख लाभ.",
    ta: "கர்ப்பிணிப் பெண்கள் மற்றும் பாலூட்டும் தாய்மார்களின் சுகாதாரம் மற்றும் ஊட்டச்சத்துக்காக ₹5,000 நேரடி நிபந்தனை பணப் பலன்.",
    gu: "સગર્ભા સ્ત્રીઓ અને સ્તનપાન કરાવતી માતાઓના આરોગ્ય અને પોષણ માટે ₹5,000 નો સીધો શરતી રોકડ લાભ.",
    kn: "ಗರ್ಭಿಣಿಯರು ಮತ್ತು ಹಾಲುಣಿಸುವ ತಾಯಂದಿರ ಆರೋಗ್ಯ ಮತ್ತು ಪೋಷಣೆಗಾಗಿ ₹5,000 ನೇರ ಷರತ್ತುಬದ್ಧ ನಗದು ಪ್ರಯೋಜನ.",
    ml: "ഗർഭിണികൾക്കും മുലയൂട്ടുന്ന അമ്മമാർക്കും ആരോഗ്യത്തിനും പോഷകാഹാരത്തിനുമായി ₹5,000 നേരിട്ടുള്ള സോപാധിക പണ ആനുകൂല്യം.",
    pa: "ਗਰਭਵਤੀ ਔਰਤਾਂ ਅਤੇ ਦੁੱਧ ਚੁੰਘਾਉਣ ਵਾਲੀਆਂ ਮਾਵਾਂ ਲਈ ਸਿਹਤ ਸੰਭਾਲ ਅਤੇ ਪੋਸ਼ਣ ਲਈ ₹5,000 ਦਾ ਸਿੱਧਾ ਸ਼ਰਤੀਆ ਨਕਦ ਲਾਭ।",
    or: "ଗର୍ଭବତୀ ମହିଳା ଏବଂ ସ୍ତନ୍ୟପାନ କରାଉଥିବା ମାଆମାନଙ୍କ ସ୍ୱାସ୍ଥ୍ୟ ଏବଂ ପୁଷ୍ଟିକରତା ପାଇଁ ₹୫,୦୦୦ ର ପ୍ରତ୍ୟକ୍ଷ ସର୍ତ୍ତମୂଳକ ନଗଦ ଲାଭ।",
    as: "গৰ্ভৱতী মহিলা আৰু স্তনপান কৰোৱা মাতৃসকলৰ স্বাস্থ্য আৰু পুষ্টিৰ বাবে ₹৫,০০০ ৰ প্ৰত্যক্ষ চৰ্তসাপেক্ষ নগদ লাভ।",
    mai: "गर्भवती महिला आ स्तनपान कराबय वली माता सभक स्वास्थ्य आ पोषणक लेल ₹5,000 केर सीधा सशर्त नकद लाभ।",
    sa: "गर्भवतीभ्यः स्तन्यपायिनीभ्यः च मातृभ्यः स्वास्थ्य-पोषणाय ₹५,००० प्रत्यक्ष-सशर्त-धनलाभः।",
    ur: "حاملہ خواتین اور دودھ پلانے والی ماؤں کے لیے صحت اور غذائیت کی خاطر ₹5,000 کا براہ راست مشروط نقد فائدہ۔",
    ne: "गर्भवती महिला र स्तनपान गराउने आमाहरूका लागि स्वास्थ्य र पोषणका लागि ₹५,००० को प्रत्यक्ष ससर्त नगद लाभ।",
    gom: "गुरवार बायलो आनी थन दिवपी आवयांच्या भलायके खातीर आनी पोषणा खातीर ₹५,००० चो थेट सशर्त रोख फायदो.",
    doi: "गर्भवती जनानां ते थण पुआने आलियां मात्तरें दी सेहत ते पोषण लेई ₹5,000 दा सिद्धा सशर्त नकदी लाभ।",
    brx: "ग'र्भो थानाय हिनजाव आरो दै खौनाय बिमाफोरनि देहा आरो आदारनि थाखाय ₹5,000 नि थोंजों रांआरि अनसुन्थाइ।",
    mni: "মীরোনবা নুপীশিং অমসুং খোমপীবা মমাশিংগী হকশেল অমসুং পুস্তিগীদমক লুপা ৫,০০০ হকথেংননা পীবা কন্দিসনেল কেস বেনিফিৎ।",
    sd: "حامله عورتن ۽ ٻار کي کير پياريندڙ ماين لاءِ صحت ۽ غذائيت خاطر ₹5,000 سڌي شرطي نقد رقم جو فائدو.",
    sat: "ᱜᱚᱨᱵᱷᱚᱵᱚᱛᱤ ᱛᱤᱨᱞᱟᱹ ᱟᱨ ᱛᱳᱣᱟ ᱧᱩᱧᱩ ᱟᱭᱳ ᱠᱚᱣᱟᱜ ᱦᱚᱲᱢᱚ ᱟᱨ ᱯᱩᱥᱴᱤ ᱞᱟᱹᱜᱤᱫ ₹᱕,᱐᱐᱐ ᱥᱚᱡᱷᱮ ᱥᱚᱨᱛᱷᱟᱱ ᱠᱟᱹᱣᱰᱤ ᱞᱟᱵᱷ।",
    ks: "گَربھوَتی زَنانَن تہٕ دۄد دِنہٕ والیٚن ماجَن ہٕنٛز صِحَت تہٕ غِذا خٲطرٕ ₹5,000 براہِ راست نَقد فایدٕ۔"
  },
