  "Monthly welfare pension support for elderly citizens, widows, and persons with disability living below the poverty line.": {
    hi: "गरीबी रेखा से नीचे रहने वाले बुजुर्ग नागरिकों, विधवाओं और दिव्यांगों के लिए मासिक कल्याण पेंशन सहायता।",
    bn: "দারিদ্র্যসীমার নিচে বসবাসকারী প্রবীণ নাগরিক, বিধবা এবং প্রতিবন্ধীদের জন্য মাসিক কল্যাণ পেনশন সহায়তা।",
    te: "దారిద్య్రరేఖకు దిగువన నివసిస్తున్న వృద్ధులు, వితంతువులు మరియు దివ్యాంగులకు నెలవారీ సంక్షేమ పెన్షన్ మద్దతు.",
    mr: "दारिद्र्यरेषेखालील वृद्ध नागरिक, विधवा आणि दिव्यांगांसाठी मासिक कल्याणकारी पेन्शन सहाय्य.",
    ta: "வறுமைக் கோட்டிற்கு கீழ் வாழும் முதியவர்கள், விதவைகள் மற்றும் மாற்றுத்திறனாளிகளுக்கான மாதாந்திர நல ஓய்வூதிய ஆதரவு.",
    gu: "ગરીબી રેખા નીચે જીવતા વરિષ્ઠ નાગરિકો, વિધવાઓ અને દિવ્યાંગો માટે માસિક કલ્યાણ પેન્શન સહાય.",
    kn: "ಬಡತನ ರೇಖೆಗಿಂತ ಕೆಳಗಿರುವ ಹಿರಿಯ ನಾಗರಿಕರು, ವಿಧವೆಯರು ಮತ್ತು ಅಂಗವಿಕಲರಿಗೆ ಮಾಸಿಕ ಕಲ್ಯಾಣ ಪಿಂಚಣಿ ಬೆಂಬಲ.",
    ml: "ദാരിദ്ര്യരേഖയ്ക്ക് താഴെയുള്ള മുതിർന്ന പൗരന്മാർക്കും വിധവകൾക്കും ഭിന്നശേഷിക്കാർക്കും പ്രതിമാസ ക്ഷേമ പെൻഷൻ പിന്തുണ.",
    pa: "ਗਰੀਬੀ ਰੇਖਾ ਤੋਂ ਹੇਠਾਂ ਰਹਿਣ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨਾਗਰਿਕਾਂ, ਵਿਧਵਾਵਾਂ ਅਤੇ ਦਿਵਿਆਂਗਾਂ ਲਈ ਮਹੀਨਾਵਾਰ ਭਲਾਈ ਪੈਨਸ਼ਨ ਸਹਾਇਤਾ।",
    or: "ଦାରିଦ୍ର୍ୟ ସୀମାରେଖା ତଳେ ଥିବା ବରିଷ୍ଠ ନାଗରିକ, ବିଧବା ଏବଂ ଭିନ୍ନକ୍ଷମଙ୍କ ପାଇଁ ମାସିକ କଲ୍ୟାଣ ପେନସନ ସହାୟତା।",
    as: "দৰিদ্ৰতা সীমাৰেখাৰ তলৰ জ্যেষ্ঠ নাগৰিক, বিধৱা আৰু দিব্যাংগসকলৰ বাবে মাহেকীয়া কল্যাণ পেন্সন সাহায্য।",
    mai: "गरीबी रेखा सँ नीचा रहय वला बुजुर्ग नागरिक, विधवा आ दिव्यांगक लेल मासिक कल्याण पेंशन सहायता।",
    sa: "दारिद्र्य-रेखायाः अधः स्थितानां ज्येष्ठानां, विधवाभ्यः, दिव्याङ्गेभ्यः च मासिक-कल्याण-पेन्शन-साहाय्यम्।",
    ur: "غربت کی لکیر سے نیچے رہنے والے بزرگ شہریوں، بیواؤں اور معذور افراد کے لیے ماہانہ فلاحی پنشن کی امداد۔",
    ne: "गरिबीको रेखामुनि रहेका ज्येष्ठ नागरिक, एकल महिला तथा अपाङ्गता भएका व्यक्तिहरूका लागि मासिक कल्याणकारी पेन्सन सहयोग।",
    gom: "गोरिबांचे रेषेखालां रावपी जाण्टे मनीस, विधवां आनी दिव्यांगां खातीर म्हायन्याचो पेन्शन पालव.",
    doi: "गरीबी रेखा थमां थल्ले र्होने आहले बुजुर्ग नागरिकें, बिधवाएं ते दिव्यांगे लेई मासिक कल्याण पेंशन सहायता।",
    brx: "दोलिथिया गाहायाव थानाय बैसो गोरा सुबुं, रान्दि आरो दिब्यांगफोरनो दानारि अनसुन्थाइ पेन्सन मदद।",
    mni: "লাইরবগী লৈমায়খাগী মখাদা লৈবা অহাল ওইরবা নাগরিকশিং, লুখ্রাবীশিং অমসুং অৱাৎপা লৈবা মীওইশিংগী থাগী ৱেলফিয়ার পেন্সন সপোর্ত।",
    sd: "غربت جي لڪير کان هيٺ رهندڙ بزرگ شهرين، بيواهن ۽ معذورن لاءِ ماهوار فلاحي پينشن امداد.",
    sat: "ᱨᱮᱸᱜᱮᱡ ᱜᱟᱨ ᱞᱟᱛᱟᱨ ᱨᱤᱱ ᱵᱩᱰᱷᱟᱹ ᱦᱚᱲ, ᱨᱟᱺᱰᱤ ᱟᱨ ᱵᱤᱠᱞᱟᱝ ᱠᱚ ᱞᱟᱹᱜᱤᱫ ᱪᱟᱸᱫᱚᱠᱤᱭᱟᱹ ᱵᱷᱟᱹᱞᱟᱹᱭ ᱯᱮᱱᱥᱚᱱ ᱜᱚᱲᱚ।",
    ks: "غُربَتٕچ لَکیٖرِ تل رۆزَن والؠن بُزُرگَن، رانٛڈؠن تہٕ مَعذوٗرَن خٲطرٕ رؠتہٕ وار پینشَن مَدَتھ۔"
  },

