    kn: "ನಿಮ್ಮ ಸ್ಥಳ ಮತ್ತು ಪ್ರೊಫೈಲ್‌ಗೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಮ್ಯಾಪ್ ಮಾಡಲಾದ ಅಧಿಕೃತ ನಿಯಂತ್ರಕ ನೀತಿ ಪ್ರಚೋದಕಗಳು.",
