    mai: "अहाँक स्थान आ प्रोफाइल सं स्वचालित रूप सं मैप कएल आधिकारिक नियामक नीति ट्रिगर।",
    sat: "ᱟᱢᱟᱜ ᱴᱷᱟᱶ ᱟᱨ ᱯᱨᱚᱯᱷᱟᱭᱤᱞ ᱥᱟᱶ ᱟᱡ ᱛᱮ ᱢᱮᱯ ᱟᱠᱟᱱ ᱥᱚᱨᱠᱟᱨᱤ ᱱᱤᱭᱟᱹᱢ ᱟᱹᱨᱤ ᱴᱨᱤᱜᱚᱨ।",
    brx: "नोंथांनि जायगा आरो प्रफाइलजों गावआरि मेप खालामनाय अफिसियेल नियामक नीति ट्रिगर।",
    doi: "तुहाड़े स्थान ते प्रोफ़ाइल कन्नै स्वचालित रूप कन्नै मैप कीते गेदे आधिकारिक नियामक नीति ट्रिगर।",
