    sa: "राजस्थान प्रत्यक्ष लाभ अंतरणं जन आधार २.० एकीकरणं च",
    ne: "राजस्थान प्रत्यक्ष लाभ हस्तान्तरण र जन आधार २.० एकीकरण",
    gom: "राजस्थान थेट लाभ हस्तांतरण आनी जन आधार 2.0 एकत्रीकरण",
    ks: "راجستھان ڈائریکٹ بینیفٹ ٹرانسفر تہٕ جن آدھار 2.0 انضمام",
    sd: "راجسٿان ڊائريڪٽ بينيفٽ ٽرانسفر ۽ جن آڌار 2.0 انٽيگريشن",
    mai: "राजस्थान प्रत्यक्ष लाभ हस्तांतरण आ जन आधार 2.0 एकीकरण",
    sat: "ᱨᱟᱡᱚᱥᱛᱷᱟᱱ ᱥᱚᱡᱷᱮ ᱞᱟᱵᱷ ᱵᱷᱮᱡᱟ ᱟᱨ ᱡᱚᱱ ᱟᱫᱷᱟᱨ ᱒.᱐ ᱢᱮᱥᱟ",
