    doi: "राजस्थान प्रत्यक्ष लाभ हस्तांतरण ते जन आधार 2.0 एकीकरण",
    mni: "রাজস্থান দাইরেক্ত বেনিফিৎ ত্রান্সফর অমসুং জন আধার 2.0 ইন্টিগ্রেসন"
